import{z as n,x as i,o as E,c as t,q as r,j as A,D as e,d as B,s as l,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"roofline 的深化与收束","description":"","frontmatter":{"title":"roofline 的深化与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/par-roofline-map.md","filePath":"cs/par-roofline-map.md","lastUpdated":1791063341000}'),p={name:"cs/par-roofline-map.md"};function f(d,a,c,m,h,D){const o=i("Mermaid");return E(),t("div",null,[a[2]||(a[2]=r('<h1 id="roofline-的深化与收束" tabindex="-1">roofline 的深化与收束 <a class="header-anchor" href="#roofline-的深化与收束" aria-label="Permalink to &quot;roofline 的深化与收束&quot;">​</a></h1><div class="epigraph"><p>屋顶图不教你改代码，它只回答一个问题：这个内核现在撞在哪堵墙上。深化的部分，是把「多少字节真的动了」数对。</p><footer>—— 据 Williams, Waterman, and Patterson, Roofline: An Insightful Visual Performance Model, CACM 2009 整理</footer></div><p><a href="/cs/par-numa">上一课</a>把有效带宽按节点分了档。本课程从 <a href="/cs/par-pram-to-practice">PRAM 的理想账</a>出发，经过 OpenMP/MPI、<a href="/cs/par-data-parallel-patterns">数据并行的模式</a>、<a href="/cs/par-task-parallel">任务并行</a>、<a href="/cs/par-lockfree">lock-free</a>、<a href="/cs/par-simd-vectorization">SIMD 与向量化</a>与 NUMA，最后要一张图把所有账并拢。<a href="/cs/roofline-model">Roofline 模型</a>已画好屋顶：横轴算术强度 \\(I\\)，纵轴可达性能 \\(P\\le\\min(F, B\\cdot I)\\)。本课做三件深化——点怎么算才不撒谎、屋顶怎么分层读、优化次序怎么定——并以此把全课程收进一张图。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>深化的缺口有三个。其一，点的位置会撒谎：强度若用「算法最少字节」算，缓存复用就被算没了——同一段代码在 L2 屋顶与 DRAM 屋顶上是两个点，你优化的是哪一个必须先说清。其二，屋顶不止一横一斜：每层存储一条斜线（斜率是该层带宽）、算力一条横线，脊点 \\(I^{*}=F/B\\) 把「向量化值多少」变成一个可算的数。其三，优化次序：先垂直爬到当前屋顶，还是先右移强度，做反了力气全白费。错法：拿矩阵乘的理论强度宣布自己「计算受限」，实测点却贴着 DRAM 斜线爬——朴素三重循环的每个 FLOP 都在搬字节，强度不过零点几个 FLOP 每字节。</p><p><span class="marginnote">数字实例：脊点 \\(I^{*}=F/B\\) 就是拿算力除带宽——单核 \\(50\\) GFLOP/s、\\(25\\) GB/s 时 \\(I^{*}=2\\) FLOP/字节。强度 \\(0.25\\) 的内核在斜线上（搬字节忙），强度 \\(40\\) 的在平顶上（算得忙）；你的点离脊点多远，直接给出「向量化还值几个钱」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测量协议先立：算力与字节都取实测——FLOP 事件与各层缓存、DRAM 的读写字节数来自 <a href="/cs/pmu-counters">PMU 计数器</a>，点画在 \\(\\min(F, B\\cdot I)\\) 的图上，配<a href="/cs/strong-weak-scaling">强扩展与弱扩展</a>的曲线一起看：扩展一旦拐弯，先查拐点是不是带宽墙，再怀疑同步——<a href="/cs/gustafson-law">Gustafson 定律</a>「串行段不变」的假设在带宽墙前最先失守。优化次序按图行事：<a href="/cs/par-simd-vectorization">SIMD 与向量化</a>抬的是横线（峰值 \\(F\\)），<a href="/cs/par-data-parallel-patterns">数据并行的融合</a>与分块右移点（抬 \\(I\\)），<a href="/cs/par-numa">NUMA</a>与合并抬的是有效 \\(B\\)——上一课的分档直接进斜率；无锁重试与伪共享不改变屋顶，只把点往下拽。</p>',8)),(E(),A(s,null,{default:e(()=>[l(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%A8%A1%E5%9E%8B%E8%B4%A6%EF%BC%9Awork-span%20%E7%9A%84%20W%20%E4%B8%8E%20S%22%5D%20--%3E%20P%5B%22%E5%AE%9E%E7%8E%B0%E8%B4%A6%EF%BC%9Aroofline%22%5D%0A%20%20P%20--%3E%20DP%5B%22%E6%A8%A1%E5%BC%8F%E4%B8%8E%E8%9E%8D%E5%90%88%EF%BC%9A%E5%8F%B3%E7%A7%BB%E5%BC%BA%E5%BA%A6%20I%22%5D%0A%20%20P%20--%3E%20SIMD%5B%22SIMD%EF%BC%9A%E6%8A%AC%E9%AB%98%E5%B3%B0%E5%80%BC%20F%22%5D%0A%20%20P%20--%3E%20NUMA%5B%22NUMA%EF%BC%9A%E6%9C%89%E6%95%88%E5%B8%A6%E5%AE%BD%20B%20%E5%88%86%E6%A1%A3%22%5D%0A%20%20P%20--%3E%20LF%5B%22%E4%BA%89%E7%94%A8%E4%B8%8E%E4%BC%AA%E5%85%B1%E4%BA%AB%EF%BC%9A%E7%82%B9%E4%B8%8B%E6%8B%BD%22%5D%0A%20%20DP%20--%3E%20RL%5B%22min(F%2C%20B%C2%B7I)%20%E5%AE%9A%E5%A2%99%E4%BD%8D%22%5D%0A%20%20SIMD%20--%3E%20RL%0A%20%20NUMA%20--%3E%20RL%0A%20%20LF%20--%3E%20RL%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制一：强度是分母的函数——分母取哪一层的字节，决定你跟哪张屋顶比；<a href="/cs/cache-oblivious">缓存无关结构</a>与分块的机制，就是把分母从 DRAM 字节换成 L2 字节，同一个算法在图上换了位置。机制二：脊点的账——单核几十 GFLOP/s 对几十 GB/s，脊点只有个位数 FLOP 每字节：SAXPY 强度约 \\(1/6\\)，天生贴斜线，向量化救不了它；矩阵乘分块后强度上百，才配得上平顶。机制三：两张图并读——<a href="/cs/work-span-model">work-span</a> 回答「值不值得并行」（跨度封顶加速），roofline 回答「并行了以后卡在哪」（墙位定上限）；前者是算法的账，后者是机器的账，合起来才是完整账本。</p><p><span class="marginnote">WWP 2009 原文的两个样例正是两端：SAXPY 强度约 \\(0.17\\) FLOP/字节，永远在斜线上；朴素三重循环矩阵乘强度也只有零点几，分块之后才爬上平顶——「算法上限」与「实现位置」是两件事。</span></p><p>方法一节那张图是「全课程各本账怎么并拢」；实际动手时「先治哪个」的判断顺序，是另一个问题。</p>',4)),(E(),A(s,null,{default:e(()=>[l(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E5%AE%9E%E6%B5%8B%E7%82%B9%E7%94%BB%E4%B8%8A%20roofline%22%5D%20--%3E%20Q1%7B%22%E7%82%B9%E8%B4%B4%E7%9D%80%E5%93%AA%E5%A0%B5%E5%A2%99%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%96%9C%E7%BA%BF%3A%20%E5%B8%A6%E5%AE%BD%E5%8F%97%E9%99%90%22%7C%20B1%5B%22%E5%85%88%E6%8A%AC%20I%3A%20%E8%9E%8D%E5%90%88%E4%B8%8E%E5%88%86%E5%9D%97%E5%8F%B3%E7%A7%BB%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%A8%AA%E7%BA%BF%3A%20%E7%AE%97%E5%8A%9B%E5%8F%97%E9%99%90%22%7C%20B2%5B%22%E5%85%88%E6%8A%AC%20F%3A%20SIMD%20%E5%90%91%E9%87%8F%E5%8C%96%22%5D%0A%20%20Q1%20--%3E%7C%22%E7%A6%BB%E4%B8%A4%E5%A0%B5%E5%A2%99%E9%83%BD%E8%BF%9C%22%7C%20B3%5B%22%E5%85%88%E6%B2%BB%E4%BA%89%E7%94%A8%E4%B8%8E%E4%BC%AA%E5%85%B1%E4%BA%AB%3A%20%E7%82%B9%E8%A2%AB%E4%B8%8B%E6%8B%BD%22%5D%0A%20%20B1%20--%3E%20R%5B%22%E6%94%B9%E5%AE%8C%E9%87%8D%E6%B5%8B%20%E9%87%8D%E6%96%B0%E7%94%BB%E7%82%B9%22%5D%0A%20%20B2%20--%3E%20R%0A%20%20B3%20--%3E%20R%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">常见误区：一上来就猛调 SIMD。若点在斜线上（带宽受限），把算力屋顶抬到天上去也不会变快——像在堵死的独木桥旁边再修一条高速引道，车照样过不了河。先看点在哪堵墙上，再决定力气往哪花。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不进集群：网络进账后屋顶要多一维通信项，超出共享内存模型的边界。GPU 与专用加速器各有自己的屋顶形状，归专门的 GPU 编程课。roofline 也不管延迟敏感的尾延迟、能耗与可靠性——它是一张带宽-算力的静态图，动态行为要回到计数器与剖析器。模型的理想账（PRAM）与机器的账（本课）永远不该只用其中一张下结论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>点要用实测字节算：算法强度撒谎，同一段代码在 L2 与 DRAM 屋顶上是两个点。</li><li>脊点 \\(I^{*}=F/B\\) 量化向量化值多少；SAXPY 贴斜线，分块矩阵乘才上平顶。</li><li>优化次序：先爬到当前屋顶，再右移强度；NUMA 分档进斜率，争用把点下拽。</li><li>work-span 与 roofline 并读：值不值得并行，并行之后卡在哪。</li><li>本课程从 PRAM 走到屋顶图收束：模型给上限与正确性，机器给墙，写并行程序就是在两者之间翻译。</li><li>出处：Williams, Waterman, and Patterson, CACM 2009。</li></ul><p><span class="marginnote">直觉类比：把 roofline 想成运力图——斜线段是「每升油能拉多少货」受限的省道（带宽封顶），平顶是「车再多也只开这么快」的高速（算力封顶）。算术强度就是「每搬一字节捎带几次运算」的装载率：装得越满越靠右，越早撞上算力横线。</span></p>',6))])}const C=n(p,[["render",f]]);export{_ as __pageData,C as default};
